  padding: 1.5rem 1.75rem;
  margin-bottom: 1.25rem;
  box-shadow: var(--shadow);
  transition: border-color 0.2s;
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

.form-field fieldset {
  border: none;
}

.form-field legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  padding: 0;
  margin-bottom: 0.35rem;
  width: 100%;
}

.question-number {
  display: inline-block;
  background: linear-gradient(135deg, #6c74e8, #a57bef);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 0.2em 0.6em;
  border-radius: 4px;
  margin-bottom: 0.6rem;
}

.help-text {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.4rem;
