  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.result-breakdown li {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.result-breakdown li::before {
  content: "";
  display: inline-block;
  width: 10px;
  height: 10px;
  min-width: 10px;
  border-radius: 50%;
}

.result-breakdown li.correct::before {
  background: var(--success);
}

.result-breakdown li.incorrect::before {
  background: var(--error);
}

.result-breakdown li.correct {
  color: var(--success);
}

.result-breakdown li.incorrect {
  color: var(--error);
}

