+  font-size: 0.9rem;
+  font-weight: 600;
+  padding: 0.5rem 1.25rem;
+  border-radius: 7px;
+  cursor: pointer;
+  transition: background 0.15s, color 0.15s;
+}
+
+.btn-retry:hover {
+  background: color-mix(in srgb, var(--accent) 15%, transparent);
+}
+
+.btn-retry:focus-visible {
+  outline: 3px solid var(--accent);
