        <label class="option-label">
          <input
            type="checkbox"
            name="${q.id}"
            value="${opt.value}"
            aria-describedby="${q.helpText ? helpId : ""}${q.helpText ? " " : ""}${errorId}"
          />
          <span>${opt.label}</span>
