      .map((o) => o.label)
      .join(", ");
    return `<li class="${isCorrect ? "correct" : "incorrect"}">
      Q${idx + 1}: ${isCorrect ? "Correct" : `Incorrect — correct answer${q.correct.size > 1 ? "s" : ""}: ${correctLabels}`}
