  clearErrors();

  let firstErrorField = null;
  let valid = true;

  QUESTIONS.forEach((q) => {
    const selections = getSelections(q.id);
    if (selections.length === 0) {
      valid = false;
      const field = document.getElementById(`field-${q.id}`);
      const errorEl = document.getElementById(`${q.id}-error`);
      field.classList.add("has-error");
      errorEl.textContent = "Please select at least one answer.";
      if (!firstErrorField) firstErrorField = field.querySelector("input");
    }
  });

  if (!valid) {
    firstErrorField?.focus();
    return;
  }

  const score = QUESTIONS.reduce((acc, q) => {
    const selected = new Set(getSelections(q.id));
    return acc + (setsEqual(selected, q.correct) ? 1 : 0);
  }, 0);

  showResults(score);
});

document.getElementById("btn-retry").addEventListener("click", () => {
  clearErrors();
  document.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
    cb.checked = false;
