+        <label class="option-label">
+          <input
+            type="checkbox"
+            name="${q.id}"
+            value="${opt.value}"
+            aria-describedby="${q.helpText ? helpId : ""}${q.helpText ? " " : ""}${errorId}"
+          />
+          <span>${opt.label}</span>
+        </label>`
+      )
+      .join("");
+
+    field.innerHTML = `
+      <fieldset aria-describedby="${q.helpText ? helpId + " " : ""}${errorId}">
+        <legend>${numBadge} ${q.text}</legend>
+        ${helpHtml}
+        <div class="options" role="group">
+          ${optionsHtml}
+        </div>
+        <p class="field-error" id="${errorId}" role="alert" aria-live="polite"></p>
+      </fieldset>`;
+
+    form.insertBefore(field, form.querySelector(".quiz-footer"));
+  });
+}
+
+function getSelections(questionId) {
+  return Array.from(
+    document.querySelectorAll(`input[name="${questionId}"]:checked`)
+  ).map((el) => el.value);
+}
+
+function setsEqual(a, b) {
+  return a.size === b.size && [...a].every((v) => b.has(v));
+}
+
+function clearErrors() {
+  document.querySelectorAll(".form-field.has-error").forEach((el) => {
+    el.classList.remove("has-error");
+    el.querySelector(".field-error").textContent = "";
+  });
+}
+
+function showResults(score) {
+  const results = document.getElementById("results");
+  const scoreEl = document.getElementById("score-value");
+  const msgEl = document.getElementById("result-message");
+  const breakdown = document.getElementById("result-breakdown");
+
+  scoreEl.textContent = `${score} / ${QUESTIONS.length}`;
+  msgEl.textContent =
+    score === QUESTIONS.length
+      ? "Perfect score! You really know your languages. 🎉"
+      : score >= 2
+      ? "Great work — you're well versed in programming languages!"
+      : "Good effort! Review the answers and try again.";
+
+  breakdown.innerHTML = QUESTIONS.map((q, idx) => {
+    const selected = new Set(getSelections(q.id));
+    const isCorrect = setsEqual(selected, q.correct);
+    const correctLabels = q.options
+      .filter((o) => q.correct.has(o.value))
+      .map((o) => o.label)
+      .join(", ");
+    return `<li class="${isCorrect ? "correct" : "incorrect"}">
+      Q${idx + 1}: ${isCorrect ? "Correct" : `Incorrect — correct answer${q.correct.size > 1 ? "s" : ""}: ${correctLabels}`}
+    </li>`;
+  }).join("");
+
+  results.classList.add("visible");
+  results.removeAttribute("hidden");
+  results.focus();
+}
+
+document.getElementById("quiz-form").addEventListener("submit", (e) => {
+  e.preventDefault();
+  clearErrors();
+
+  let firstErrorField = null;
+  let valid = true;
+
+  QUESTIONS.forEach((q) => {
+    const selections = getSelections(q.id);
+    if (selections.length === 0) {
+      valid = false;
+      const field = document.getElementById(`field-${q.id}`);
+      const errorEl = document.getElementById(`${q.id}-error`);
+      field.classList.add("has-error");
+      errorEl.textContent = "Please select at least one answer.";
+      if (!firstErrorField) firstErrorField = field.querySelector("input");
+    }
+  });
+
+  if (!valid) {
+    firstErrorField?.focus();
+    return;
+  }
+
+  const score = QUESTIONS.reduce((acc, q) => {
+    const selected = new Set(getSelections(q.id));
+    return acc + (setsEqual(selected, q.correct) ? 1 : 0);
+  }, 0);
+
+  showResults(score);
+});
+
+document.getElementById("btn-retry").addEventListener("click", () => {
+  clearErrors();
+  document.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
+    cb.checked = false;
+  });
+  document.querySelectorAll(".option-label").forEach((label) => {
+    label.removeAttribute("aria-checked");
+  });
+  const results = document.getElementById("results");
+  results.classList.remove("visible");
+  results.setAttribute("hidden", "");
+
+  // Return focus to first question
+  const firstInput = document.querySelector('input[type="checkbox"]');
+  firstInput?.focus();
+});
+
+buildQuiz();
+
')

